// Extract thông tin từ Telegram message
const msg = $input.first().json;
const message = msg.message;

if (!message || !message.text) {
  // Bỏ qua tin nhắn không có text (sticker, photo, etc.)
  return [];
}

return [{
  json: {
    user_id: String(message.from.id),
    text: message.text,
    chat_id: message.chat.id,
    first_name: message.from.first_name || 'bạn',
    is_command: message.text.startsWith('/')
  }
}];

// Merge session context + build Haiku classifier input
const msg = $('Extract Message').first().json;
const sessionRows = $input.first().json;

// sessionRows là array từ Supabase (có thể rỗng)
const sessionRow = Array.isArray(sessionRows) && sessionRows.length > 0 
  ? sessionRows[0] 
  : null;
const sessionContext = sessionRow ? (sessionRow.session_context || {}) : {};

// Build system prompt cho Haiku classifier
const systemPrompt = `Bạn là bộ phân loại yêu cầu marketing. Phân tích tin nhắn và trả về JSON chính xác.

Skills có sẵn:
- 00-ke-hoach-mkt: lập kế hoạch marketing tổng thể
- 01-lich-noi-dung: lịch nội dung, content calendar
- 02-brief-chien-dich: brief chiến dịch quảng cáo
- 03-danh-gia-hieu-suat: đánh giá, phân tích hiệu suất ads
- 04-script-video: viết script video TikTok/Reels
- 05-copy-quang-cao: viết copy quảng cáo Meta/TikTok/Google/Zalo
- 06-brief-ugc-egc: brief cho creator UGC/EGC
- 08-nghien-cuu-doi-thu: nghiên cứu đối thủ cạnh tranh
- 09-insight-khach-hang: insight khách hàng, persona
- 30-retention-strategy: giữ chân khách hàng, loyalty
- 31-winback-campaign: win-back khách đã bỏ

Session context hiện tại: ${JSON.stringify(sessionContext)}

Trả về JSON với format:
{
  "skill_id": "tên-skill hoặc null",
  "mode": "product hoặc personal_brand hoặc null",
  "industry": "spa/clinic/fnb/gym/giao-duc/ecommerce/khac hoặc null",
  "output_format": "telegram hoặc full",
  "needs_clarification": true hoặc false,
  "clarification_question": "câu hỏi nếu needs_clarification=true, null nếu không cần",
  "detected_context": {"business_name": null, "product": null}
}

Ghi chú:
- output_format = "full" chỉ khi user gõ /full hoặc nói "file đầy đủ"/"Google Sheet"/"Excel"
- needs_clarification = true nếu không rõ skill nào phù hợp
- Chỉ trả về JSON thuần, không giải thích`;

return [{
  json: {
    system: systemPrompt,
    user_text: msg.text,
    user_id: msg.user_id,
    chat_id: msg.chat_id,
    first_name: msg.first_name,
    session_context: sessionContext,
    session_row_exists: sessionRow !== null
  }
}];

// Parse kết quả từ Haiku classifier
const haiku = $input.first().json;
const buildInput = $('Build Haiku Input').first().json;

let classification;
try {
  const rawText = haiku.content[0].text.trim();
  // Tách JSON ra khỏi markdown code block nếu có
  const jsonMatch = rawText.match(/```json\n?([\s\S]*?)\n?```/) || 
                    rawText.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : rawText;
  classification = JSON.parse(jsonStr);
} catch(e) {
  classification = {
    skill_id: null,
    mode: null,
    industry: null,
    output_format: 'telegram',
    needs_clarification: true,
    clarification_question: 'Bạn cần hỗ trợ gì? Ví dụ: viết kế hoạch marketing, script TikTok, copy quảng cáo, phân tích đối thủ...'
  };
}

return [{
  json: {
    ...classification,
    user_id: buildInput.user_id,
    chat_id: buildInput.chat_id,
    first_name: buildInput.first_name,
    original_text: buildInput.user_text,
    session_context: {
      ...buildInput.session_context,
      ...(classification.detected_context || {})
    }
  }
}];

// Build system prompt từ skill sections
const sections = $input.first().json;
const classify = $('Parse Classification').first().json;
const sessionContext = classify.session_context || {};
const outputFormat = classify.output_format || 'telegram';
const industry = classify.industry || sessionContext.industry || null;
const mode = classify.mode || sessionContext.mode || 'product';

// Filter sections theo mode và industry
const sectionArray = Array.isArray(sections) ? sections : [];
const filtered = sectionArray.filter(s => {
  // Luôn include nếu modes = ['all'] hoặc priority = 1
  if (s.priority === 1) return true;
  const modesOk = s.modes.includes('all') || 
                   s.modes.includes(outputFormat) || 
                   (outputFormat === 'full');
  const indOk = s.industries.includes('all') || 
                 (industry && s.industries.includes(industry));
  return modesOk && indOk;
});

// Build system prompt
let systemPrompt = `Bạn là MKT Strategist AI — trợ lý marketing chuyên nghiệp theo framework Over Powers Agency.
Ngôn ngữ: Tiếng Việt. Thuật ngữ chuyên môn giữ nguyên tiếng Anh (ROAS, CPMess, TOFU/MOFU/BOFU, USP, KPI).

Nguyên tắc cốt lõi:
1. KHÔNG trả lời chung chung. Luôn output có cấu trúc rõ ràng.
2. Hỏi trước khi làm. Nếu thiếu thông tin → hỏi tối đa 3-4 câu.
3. Benchmark Việt Nam 2025-2026 (không dùng số liệu nước ngoài).

Session context:
${JSON.stringify(sessionContext, null, 2)}

Output format: ${outputFormat === 'full' ? 'ĐẦY ĐỦ — cấu trúc hoàn chỉnh với bảng, template, checklist' : 'TELEGRAM — bullet points ngắn gọn, actionable, dưới 800 ký tự mỗi section'}
`;

// Thêm nội dung từng section
filtered.forEach(s => {
  systemPrompt += `\n\n---\n${s.content}`;
});

return [{
  json: {
    system_prompt: systemPrompt,
    sections_count: filtered.length,
    user_id: classify.user_id,
    chat_id: classify.chat_id,
    first_name: classify.first_name,
    skill_id: classify.skill_id,
    output_format: outputFormat,
    session_context: sessionContext,
    original_text: classify.original_text
  }
}];

// Format response + parse critic score
const sonnet = $('Sonnet Execute').first().json;
const critic = $input.first().json;
const context = $('Build System Prompt').first().json;

const responseText = sonnet.content[0].text;
const criticRaw = critic.content[0].text.trim();

// Parse critic: PASS|85|Comment
const criticParts = criticRaw.split('|');
const criticStatus = criticParts[0] || 'PASS';
const criticScore = parseInt(criticParts[1]) || 70;
const criticComment = criticParts[2] || '';

// Telegram giới hạn 4096 ký tự
let finalResponse = responseText;
if (finalResponse.length > 3900) {
  finalResponse = finalResponse.substring(0, 3850) + 
    '\n\n_[Phản hồi đầy đủ bị cắt. Gõ /full để nhận file hoàn chỉnh]_';
}

// Footer nhẹ cho Telegram (chỉ khi score thấp)
if (criticScore < 60) {
  finalResponse += `\n\n_⚠️ Lưu ý: Phản hồi này cần thêm thông tin để chính xác hơn. Hãy cung cấp thêm chi tiết về sản phẩm/ngành._`;
}

// Update session context
const updatedSession = {
  ...context.session_context,
  last_skill: context.skill_id,
  last_interaction: new Date().toISOString()
};

return [{
  json: {
    response: finalResponse,
    critic_status: criticStatus,
    critic_score: criticScore,
    chat_id: context.chat_id,
    user_id: context.user_id,
    skill_id: context.skill_id,
    updated_session: updatedSession
  }
}];
